const crypto = require('node:crypto');
const http = require('node:http');

http.createServer((req, res) => {
  // ❌ OLD: hashing a large body synchronously blocks the event loop
  // for the duration of the hash — other requests, timers, and events
  // all wait. For a 100MB upload this is a visible freeze.
  const hash = crypto
    .createHash('sha256')
    .update(bigData)
    .digest('hex'); // ❌ OLD: runs on the main thread
  res.end(hash);
}).listen(3000);

const http = require('node:http');

http.createServer(async (req, res) => {
  // ✅ NEW: subtle.digest returns a Promise; the heavy work runs off
  // the main thread (thread pool), so the event loop stays responsive
  // while the hash computes.
  const hash = await crypto.subtle.digest('SHA-256', bigData); // ✅ NEW
  res.end(Buffer.from(hash).toString('hex'));
}).listen(3000);

